entries[251265] = { ["name"] = "Teufelspyrolyse", ["text"] = "Wirken in 2 sek. 3 sek. Abklingzeit\nDer Zaubernde schlägt mit den Schwingen und erzeugt eine Teufelspyrolyse, die Feuerschaden verursacht und alle Gegner wegdrückt." }
